<?php get_header(); the_post(); $agent_id = get_the_ID(); ?><div class="wrap"><div class="agent-profile"><div><?php if (has_post_thumbnail()) : the_post_thumbnail('large', ['class' => 'agent-portrait']); else : ?><div class="agent-portrait agent-monogram" aria-hidden="true"><?php echo esc_html(home_search_agent_initial(get_the_title())); ?></div><?php endif; ?></div><div><a class="text-link" href="<?php echo esc_url(get_post_type_archive_link('agent')); ?>">← All agents</a><p class="eyebrow" style="margin-top:35px"><?php echo esc_html(get_post_meta($agent_id, 'agent_role', true) ?: 'Property advisor'); ?></p><h1><?php the_title(); ?></h1><div class="detail-copy"><?php the_content(); ?></div><?php $phone = get_post_meta($agent_id, 'agent_phone', true); if ($phone) : ?><p><strong>Call:</strong> <a href="tel:<?php echo esc_attr(preg_replace('/[^+0-9]/', '', $phone)); ?>"><?php echo esc_html($phone); ?></a></p><?php endif; ?><a class="button button-accent" href="<?php echo esc_url(home_search_contact_url()); ?>">Get in touch ↗</a></div></div><div class="section" style="padding-top:0"><div class="section-head"><div><span class="eyebrow">Current collection</span><h2>Homes with <?php echo esc_html(get_the_title($agent_id)); ?>.</h2></div></div><div class="card-grid"><?php $listings = new WP_Query(['post_type' => 'property', 'posts_per_page' => 9, 'meta_key' => 'agent', 'meta_value' => $agent_id]); if ($listings->have_posts()) : while ($listings->have_posts()) : $listings->the_post(); get_template_part('template-parts/property-card', null, ['id' => get_the_ID()]); endwhile; wp_reset_postdata(); else : ?><div class="empty-state"><p>No current listings for this agent.</p></div><?php endif; ?></div></div></div><?php get_footer(); ?>
